function enemyDamage(amount,label){state.enemyHp=Math.max(0,state.enemyHp-amount);log(`${label} deals ${amount} damage to ${enemyInfo().name}.`,'gold');if(state.enemyHp<=0)finish(true,`${enemyInfo().name} is defeated!`);}
function enemyGarbage(n){state.enemyGarbage+=n;$('#enemyAttack').innerHTML=`<span>⚡</span> <b>${state.enemyGarbage}</b> INCOMING`;log(`${n} corrupted line${n===1?'':'s'} sent to ${enemyInfo().name}.`,'cyan');}
function burnRows(n,label){let burned=0;for(let i=0;i<n;i++){const y=state.enemy.findIndex(row=>row.some(Boolean));if(y<0)break;state.enemy.splice(y,1);state.enemy.unshift(Array(COLS).fill(null));burned++}if(!burned)return false;enemyDamage(burned*(n===1?9:9),label);state.enemyGarbage=Math.max(0,state.enemyGarbage-burned);return true;}
function castSpell(which){if(!state.running||state.paused||state.over)return;const spell=SPELLS.find(s=>s.id===which);if(!spell)return;if(state.mana<spell.cost){toast('Not enough mana. Clear lines to recharge.');return}const now=Date.now();if((which==='veil'&&now<state.shieldUntil)||(which==='ward'&&now<state.shieldUntil)){toast('Your barrier is already active.');return}if((which==='flare'||which==='meteor'||which==='wildfire')&&!state.enemy.some(row=>row.some(Boolean))){toast('There are no enemy rows to burn yet.');return}state.mana-=spell.cost;let message=spell.name;
  switch(which){case'flare':burnRows(1,'Emberfall');break;case'veil':case'ward':state.shieldUntil=now+(which==='veil'?8000:5000);$('#shieldEffect').classList.add('active');log(`${spell.name} blocks incoming attacks.`,'cyan');break;case'hex':state.enemyHex=3;break;case'mend':state.playerHp=Math.min(100,state.playerHp+28);break;case'frost':state.enemySlowUntil=now+8000;break;case'quake':enemyGarbage(2);break;case'siphon':enemyDamage(12,'Soul Siphon');state.playerHp=Math.min(100,state.playerHp+12);break;case'spark':enemyDamage(12,'Star Spark');break;case'meteor':burnRows(2,'Meteor Rite');break;case'collapse':enemyGarbage(3);break;case'silence':state.silenceUntil=now+8000;break;case'anchor':state.playerGarbage=Math.max(0,state.playerGarbage-2);$('#incomingLabel').textContent=state.playerGarbage?`${state.playerGarbage} INCOMING ⚠`:'NO INCOMING';break;case'surge':state.attackBoost+=1;break;case'haste':state.enemyFastUntil=now+7000;break;case'drowse':state.enemyStunUntil=now+4000;break;case'thorn':state.mirrorCharges=1;break;case'phoenix':state.playerHp=Math.min(100,state.playerHp+45);break;case'blink':state.playerGarbage=Math.max(0,state.playerGarbage-3);$('#incomingLabel').textContent=state.playerGarbage?`${state.playerGarbage} INCOMING ⚠`:'NO INCOMING';break;case'nova':enemyDamage(28,'Astral Nova');break;case'beast':enemyDamage(12,'Beast Call');state.enemySlowUntil=now+5000;break;case'wildfire':burnRows(2,'Wildfire');break;case'timewell':state.playerSlowUntil=now+8000;break;}
  if(state.over)return;$('#enemyStatus').textContent=state.enemyHex?'HEXED ×3':spell.name.toUpperCase();log(`${spell.name} cast (${spell.cost} mana).`,'cyan');announce(message.toUpperCase(),'cyan');setFeed(`Magic: ${spell.name} — ${spell.desc}.`);sound('spell');updateUI();}

