const LEVEL_UNLOCKS=[3,10,25,40,70];
const ENEMIES=Array.from({length:400},(_,i)=>{const tier=Math.floor(i/10)+1,species=SPECIES[i%20],style=/Wolf|Bat|Lynx|Hound|Ape|Stag|Owl|Fox/.test(species)?'HUNTER':/Troll|Boar|Golem|Ram|Bear/.test(species)?'GUARDIAN':'MYSTIC';return {index:i,tier,style,name:`${species} ${EPITHETS[(i*7+Math.floor(i/10))%20]}`,hp:Math.min(420,65+tier*7),dropMs:Math.max(350,1180-(tier-1)*23),thinkMs:Math.max(240,800-(tier-1)*15),attackMs:Math.max(8000,27000-(tier-1)*500),magic:i%5!==0,hardDrop:Math.min(.82,.08+(tier-1)*.022),attackDamage:Math.min(34,5+Math.floor(tier*.72))}});
function readProfile(){try{const saved=JSON.parse(localStorage.getItem('runestack-player')||'null');if(!saved||typeof saved.name!=='string')return null;return {name:saved.name.slice(0,20),level:Math.max(1,Math.min(100,Number(saved.level)||1)),xp:Math.max(0,Number(saved.xp)||0),spells:Array.isArray(saved.spells)?saved.spells.filter(id=>SPELLS.some(s=>s.id===id)).slice(0,5):[]}}catch(e){return null}}
let profile=readProfile();
function playerStats(level=profile?.level||1){return {hp:100+(level-1)*2,attack:8+Math.floor((level-1)/5),mana:3+Math.floor((level-1)/10),defense:Math.min(75,Math.floor(level*.75))}}
function unlockedSlots(level=profile?.level||1){return LEVEL_UNLOCKS.filter(n=>level>=n).length}
function spellTier(spell){return Math.min(4,Math.floor(SPELLS.indexOf(spell)*5/SPELLS.length))}
function spellsForSlot(slot){return SPELLS.filter(spell=>spellTier(spell)===slot)}
function saveProfile(){if(!profile)return;try{localStorage.setItem('runestack-player',JSON.stringify(profile))}catch(e){}}
